  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.proposals-shell, .proposal-shell, .external-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 780px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1, h2, h3 {
  color: #08263a;
}

.card, .proposal-card, .external-card {
  background: #fff;
  border-radius: 24px;
  padding: 28px;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
  margin-bottom: 24px;
}

.form-title {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: center;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

label {
  display: grid;
  gap: 6px;
  color: #08263a;
  font-weight: 700;
}

input, textarea, select {
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 11px 13px;
  font: inherit;
  background: #fff;
}

.wide {
  grid-column: 1/-1;
}

.calculation, .actions, .toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin: 18px 0;
  align-items: end;
}

.calculation span {
  background: #f8f5ef;
  padding: 10px 14px;
  border-radius: 999px;
  color: #516070;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.client-link {
  background: #f8f5ef;
  padding: 12px;
  border-radius: 12px;
  word-break: break-all;
  color: #516070;
}

.success {
  color: #047857;
  font-weight: 700;
}

.error, .expired {
  color: #9f1d1d;
  font-weight: 700;
}

.muted {
  color: #667;
}

.search-box {
  flex: 1 1 320px;
}

.proposal-list {
  display: grid;
  gap: 12px;
}

.proposal-row {
  display: grid;
  grid-template-columns: auto 1.2fr 1.2fr 0.8fr auto;
  gap: 16px;
  align-items: center;
  width: 100%;
  text-align: left;
  background: #fff;
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 18px;
  padding: 16px;
  cursor: pointer;
  box-shadow: 0 10px 28px rgba(8, 38, 58, 0.06);
}

.proposal-row strong, .proposal-row small {
  display: block;
}

.proposal-row small {
  color: #516070;
}

.status {
  border-radius: 999px;
  padding: 6px 10px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  font-weight: 700;
}

.mini-link {
  border: 0;
  background: transparent;
  color: #08263a;
  text-decoration: underline;
  cursor: pointer;
  font-weight: 700;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 12px;
  margin: 20px 0;
}

.summary-grid div, .step-card, .choice-block {
  background: #f8f5ef;
  border-radius: 18px;
  padding: 16px;
}

.summary-grid strong, .summary-grid span {
  display: block;
}

.summary-grid span {
  color: #516070;
  margin-top: 4px;
}

.terms-check, .radio-card {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  background: #fff;
  border: 1px solid rgba(8, 38, 58, 0.1);
  padding: 14px;
  border-radius: 14px;
  margin: 10px 0;
  color: #516070;
}

@media (max-width: 800px) {
  .proposal-row {
    grid-template-columns: 1fr;
  }
}
.row-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.btn-danger {
  background: #9f1d1d;
  color: #fff;
}

.validity {
  background: #eef6f0;
  color: #047857;
  padding: 0.75rem 1rem;
  border-radius: 12px;
  font-weight: 700;
}

.validity.expired,
.expired {
  color: #9f1d1d;
}

.mini-link.danger {
  color: #9f1d1d;
