  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.booking-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 760px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0;
}

.booking-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 18px;
}

.booking-card, .booking-detail-card, .empty-card {
  background: #fff;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.08);
  border: 1px solid rgba(8, 38, 58, 0.08);
}

.booking-card h2 {
  margin: 12px 0 8px;
  color: #08263a;
  font-size: 1.25rem;
}

.booking-card p {
  margin: 4px 0;
  color: #516070;
}

.status-pill {
  display: inline-flex;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 700;
}

.booking-meta {
  display: grid;
  gap: 6px;
  margin: 18px 0;
  color: #08263a;
}

.booking-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.muted {
  color: #667;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 14px;
  margin: 24px 0;
}

.detail-grid div {
  background: #f8f5ef;
  border-radius: 16px;
  padding: 14px;
  display: grid;
  gap: 4px;
}

.detail-grid strong {
  color: #08263a;
}

.detail-grid span {
  color: #516070;
}

.comments {
  background: #f8f5ef;
  padding: 16px;
  border-radius: 16px;
  color: #516070;
}

.paid-badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 0.55rem 0.9rem;
  background: #047857;
  color: #fff;
  font-weight: 700;
}

.booking-meta span {
  line-height: 1.4;
}

.booking-tabs {
  display: inline-flex;
  gap: 0.5rem;
  background: rgba(8, 38, 58, 0.06);
  border-radius: 999px;
  padding: 0.35rem;
  margin: 1rem 0;
}

.booking-tabs button {
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0.7rem 1.1rem;
  color: #08263a;
  font-weight: 800;
  cursor: pointer;
}

.booking-tabs button.active {
  background: #fff;
  box-shadow: 0 8px 22px rgba(8, 38, 58, 0.08);
}

.booking-tabs span {
  display: inline-flex;
  min-width: 1.6rem;
  height: 1.6rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.16);
  color: #b58b4a;
  margin-left: 0.35rem;
}

.booking-toolbar-grid {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) repeat(4, minmax(140px, 1fr)) auto;
  gap: 0.85rem;
  align-items: end;
  margin: 1rem 0;
}

.booking-toolbar-grid label {
  display: grid;
  gap: 0.35rem;
  color: #08263a;
  font-weight: 700;
}

.booking-toolbar-grid select,
.booking-toolbar-grid input {
  min-height: 42px;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.65rem 0.75rem;
  background: #fff;
  font: inherit;
}

@media (max-width: 980px) {
  .booking-toolbar-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 640px) {
  .booking-tabs {
    width: 100%;
  }
  .booking-tabs button {
    flex: 1;
  }
  .booking-toolbar-grid {
    grid-template-columns: 1fr;
  }
