  padding: 80px 0;
  background: #f6f2ea;
  min-height: 70vh;
}

.booking-shell {
  max-width: 1120px;
  margin: 0 auto;
}

.section-head {
  margin-bottom: 28px;
  max-width: 760px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.78rem;
  color: #b58b4a;
  font-weight: 700;
}

h1 {
  color: #08263a;
  margin: 8px 0;
}

.booking-toolbar {
  display: flex;
  align-items: end;
  gap: 12px;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.search-box {
  display: grid;
  gap: 6px;
  flex: 1 1 320px;
  color: #08263a;
  font-weight: 700;
}

.search-box input {
  width: 100%;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 999px;
  padding: 12px 16px;
  background: #fff;
  color: #08263a;
  outline: none;
  box-shadow: 0 10px 25px rgba(8, 38, 58, 0.05);
}

.search-box input:focus {
  border-color: #b58b4a;
}

.btn {
  border: 0;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: #08263a;
  color: #fff;
}

.btn-secondary {
  background: #efe7da;
  color: #08263a;
}

.muted {
  color: #667;
}

.error-message {
  color: #9f1d1d;
  background: rgba(159, 29, 29, 0.08);
  border: 1px solid rgba(159, 29, 29, 0.18);
  border-radius: 14px;
  padding: 0.85rem 1rem;
}

.list-summary {
  color: #516070;
  margin: 12px 0;
}

.bookings-list {
  display: grid;
  gap: 12px;
}

.booking-list-row {
  width: 100%;
  display: grid;
  grid-template-columns: auto minmax(180px, 1.4fr) minmax(180px, 1.2fr) minmax(130px, 0.8fr) auto;
  gap: 16px;
  align-items: center;
  text-align: left;
  background: #fff;
  border: 1px solid rgba(8, 38, 58, 0.08);
  border-radius: 20px;
  padding: 18px 20px;
  cursor: pointer;
  box-shadow: 0 14px 35px rgba(8, 38, 58, 0.07);
  transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease;
}

.booking-list-row:hover {
  transform: translateY(-2px);
  box-shadow: 0 18px 45px rgba(8, 38, 58, 0.11);
  border-color: rgba(181, 139, 74, 0.38);
}

.status-pill {
  display: inline-flex;
  justify-content: center;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.12);
  color: #8a652d;
  padding: 6px 10px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
}

.booking-main,
.booking-trip,
.booking-price {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.booking-main strong,
.booking-trip strong,
.booking-price strong {
  color: #08263a;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.booking-main small,
.booking-trip small,
.booking-price small {
  color: #516070;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row-chevron {
  color: #b58b4a;
  font-size: 2rem;
  line-height: 1;
}

@media (max-width: 820px) {
  .booking-list-row {
    grid-template-columns: 1fr auto;
  }
  .status-pill,
  .booking-main,
  .booking-trip,
  .booking-price {
    grid-column: 1/2;
  }
  .row-chevron {
    grid-column: 2/3;
    grid-row: 1/span 4;
  }
}
.row-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.65rem;
}

.mini-btn {
  border: 0;
  border-radius: 999px;
  padding: 0.55rem 0.8rem;
  background: #08263a;
  color: #fff;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}

.paid-badge {
  display: inline-flex;
  border-radius: 999px;
  padding: 0.45rem 0.75rem;
  background: #047857;
  color: #fff;
  font-weight: 700;
  white-space: nowrap;
}

.balance-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(8, 38, 58, 0.45);
  display: grid;
  place-items: center;
  padding: 1rem;
}

.balance-modal {
  width: min(560px, 100%);
  background: #fff;
  border-radius: 24px;
  padding: 1.5rem;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.22);
}

.balance-modal h2 {
  margin-top: 0;
  color: #08263a;
}

.balance-modal label {
  display: grid;
  gap: 0.4rem;
  margin: 0.85rem 0;
  color: #08263a;
  font-weight: 700;
}

.balance-modal select,
.balance-modal textarea {
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.75rem;
  font: inherit;
}

.modal-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: 1rem;
}

@media (max-width: 820px) {
  .row-actions {
    grid-column: 1/3;
    justify-content: flex-start;
  }
}
.blocked-badge {
  display: inline-flex;
  border-radius: 999px;
  padding: 0.45rem 0.75rem;
  background: #efe7da;
  color: #8a652d;
  font-weight: 700;
  white-space: nowrap;
}

.deposit-btn {
  background: #047857;
}

.booking-clarity {
  min-width: 260px;
}

.booking-clarity small {
  display: block;
  line-height: 1.35;
}

.booking-tabs {
  display: inline-flex;
  gap: 0.5rem;
  background: rgba(8, 38, 58, 0.06);
  border-radius: 999px;
  padding: 0.35rem;
  margin: 1rem 0;
}

.booking-tabs button {
  border: 0;
  border-radius: 999px;
  background: transparent;
  padding: 0.7rem 1.1rem;
  color: #08263a;
  font-weight: 800;
  cursor: pointer;
}

.booking-tabs button.active {
  background: #fff;
  box-shadow: 0 8px 22px rgba(8, 38, 58, 0.08);
}

.booking-tabs span {
  display: inline-flex;
  min-width: 1.6rem;
  height: 1.6rem;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(181, 139, 74, 0.16);
  color: #b58b4a;
  margin-left: 0.35rem;
}

.booking-toolbar-grid {
  display: grid;
  grid-template-columns: minmax(220px, 1.4fr) repeat(4, minmax(150px, 1fr));
  gap: 0.85rem;
  align-items: end;
}

.booking-toolbar-grid label {
  display: grid;
  gap: 0.35rem;
  color: #08263a;
  font-weight: 700;
}

.booking-toolbar-grid select,
.booking-toolbar-grid input {
  min-height: 42px;
  border: 1px solid rgba(8, 38, 58, 0.16);
  border-radius: 14px;
  padding: 0.65rem 0.75rem;
  background: #fff;
  font: inherit;
}

@media (max-width: 980px) {
  .booking-toolbar-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 640px) {
  .booking-tabs {
    width: 100%;
  }
  .booking-tabs button {
    flex: 1;
  }
  .booking-toolbar-grid {
    grid-template-columns: 1fr;
  }
